3	// This file implements ListProviders and HealthCheck for the FizeauService service.
4	// It lives in the root package to avoid import cycles; provider config data is
5	// injected via the ServiceConfig interface defined in service.go.
6	//
7	// Note: We cannot import agent/config or provider/openai here because both
8	// packages import the root agent package, creating a cycle. Provider probing
9	// is done inline using net/http.
10	
11	import (
12		"context"
13		"encoding/json"
14		"fmt"
15		"io"
16		"net/http"
17		"os"
18		"strings"
19		"sync"
20		"time"
