22		"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
23		claudeharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/claude"
24		codexharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/codex"
25	)
26	
27	const (
28		defaultQuotaRefreshDebounce     = 15 * time.Minute
29		defaultQuotaRefreshStartupWait  = 2 * time.Second
30		defaultQuotaRefreshProbeTimeout = 30 * time.Second
31	)
32	
33	// healthCheckClaudeQuotaRefresher is the function used to probe Claude's direct
34	// PTY quota. It is a package-level variable so tests can substitute a fake
35	// without spawning real harness sessions.
36	var healthCheckClaudeQuotaRefresher = func(timeout time.Duration) ([]harnesses.QuotaWindow, *harnesses.AccountInfo, error) {
37		return claudeharness.ReadClaudeQuotaViaPTY(timeout)
38	}
39	
40	var healthCheckCodexQuotaRefresher = func(timeout time.Duration) ([]harnesses.QuotaWindow, error) {
41		return codexharness.ReadCodexQuotaViaPTY(timeout)
42	}
43	
44	var healthCheckCodexSessionQuotaReader = func() (*codexharness.CodexQuotaSnapshot, bool) {
45		return codexharness.ReadCodexQuotaFromSessionTokenCounts()
46	}
