48	var healthCheckQuotaProbeMu sync.RWMutex
49	
50	var primaryQuotaRefresh = &quotaRefreshCoordinator{
51		lastAttempt: make(map[string]time.Time),
52		inFlight:    make(map[string]bool),
53	}
54	
55	type quotaRefreshCoordinator struct {
56		mu          sync.Mutex
57		lastAttempt map[string]time.Time
58		inFlight    map[string]bool
59	}
60	
61	type quotaRefreshMode int
62	
63	const (
64		quotaRefreshAsync quotaRefreshMode = iota
65		quotaRefreshStartup
66	)
67	
68	type quotaRefreshPolicy struct {
69		debounce     time.Duration
70		startupWait  time.Duration
71		probeTimeout time.Duration
72	}
73	
74	type quotaCacheStatus struct {
75		needsRefresh bool
76		usable       bool
77	}
78	
79	type providerProbeResult struct {
80		status           string
81		modelCount       int
82		caps             []string
83		detail           string
84		endpointName     string
85		baseURL          string
86		endpointStatuses []EndpointStatus
87	}
