89	func (s *service) ensurePrimaryQuotaRefresh(ctx context.Context, mode quotaRefreshMode) {
90		policy := s.quotaRefreshPolicy()
91		var waits []<-chan struct{}
92		for _, name := range []string{"claude", "codex"} {
93			status := primaryQuotaCacheStatus(name, policy.debounce)
94			if !status.needsRefresh {
95				continue
96			}
97			done := requestPrimaryQuotaRefresh(ctx, name, policy)
98			if mode == quotaRefreshStartup && !status.usable && done != nil {
99				waits = append(waits, done)
100			}
101		}
102		if mode == quotaRefreshStartup && len(waits) > 0 && policy.startupWait > 0 {
103			waitForPrimaryQuotaRefreshes(waits, policy.startupWait)
104		}
105	}
106	
107	func (s *service) quotaRefreshPolicy() quotaRefreshPolicy {
108		policy := quotaRefreshPolicy{
109			debounce:     defaultQuotaRefreshDebounce,
110			startupWait:  defaultQuotaRefreshStartupWait,
111			probeTimeout: defaultQuotaRefreshProbeTimeout,
112		}
113		if s != nil {
114			if s.opts.QuotaRefreshDebounce > 0 {
115				policy.debounce = s.opts.QuotaRefreshDebounce
116			}
117			if s.opts.QuotaRefreshStartupWait > 0 {
118				policy.startupWait = s.opts.QuotaRefreshStartupWait
119			}
120		}
121		return policy
122	}
123	
124	func (s *service) startPrimaryQuotaRefreshWorker() {
125		if s == nil || s.opts.QuotaRefreshInterval <= 0 {
126			return
127		}
128		ctx := s.opts.QuotaRefreshContext
129		if ctx == nil {
130			ctx = context.Background()
131		}
132		interval := s.opts.QuotaRefreshInterval
133		go func() {
134			ticker := time.NewTicker(interval)
135			defer ticker.Stop()
136			for {
137				select {
138				case <-ctx.Done():
139					return
140				case <-ticker.C:
141					s.ensurePrimaryQuotaRefresh(ctx, quotaRefreshAsync)
142				}
143			}
144		}()
145	}
146	
147	func requestPrimaryQuotaRefresh(ctx context.Context, harnessName string, policy quotaRefreshPolicy) <-chan struct{} {
148		done := make(chan struct{})
149		if ctx == nil {
150			ctx = context.Background()
151		}
152		if ctx.Err() != nil {
153			close(done)
154			return nil
155		}
156	
157		now := time.Now()
158		primaryQuotaRefresh.mu.Lock()
159		if primaryQuotaRefresh.inFlight[harnessName] {
160			primaryQuotaRefresh.mu.Unlock()
161			close(done)
162			return nil
163		}
164		if last := primaryQuotaRefresh.lastAttempt[harnessName]; !last.IsZero() && now.Sub(last) < policy.debounce {
165			primaryQuotaRefresh.mu.Unlock()
166			close(done)
167			return nil
168		}
169		primaryQuotaRefresh.lastAttempt[harnessName] = now
170		primaryQuotaRefresh.inFlight[harnessName] = true
171		primaryQuotaRefresh.mu.Unlock()
172	
173		go func() {
174			defer close(done)
175			defer func() {
176				primaryQuotaRefresh.mu.Lock()
177				primaryQuotaRefresh.inFlight[harnessName] = false
178				primaryQuotaRefresh.mu.Unlock()
179			}()
180	
181			switch harnessName {
182			case "claude":
183				refreshClaudeQuotaCache(ctx, policy.debounce, policy.probeTimeout)
184			case "codex":
185				refreshCodexQuotaCache(ctx, policy.debounce, policy.probeTimeout)
186			}
187		}()
188		return done
189	}
190	
191	func waitForPrimaryQuotaRefreshes(waits []<-chan struct{}, timeout time.Duration) {
192		deadline := time.After(timeout)
193		for _, done := range waits {
194			select {
195			case <-done:
196			case <-deadline:
197				return
198			}
199		}
200	}
201	
202	func primaryQuotaCacheStatus(harnessName string, debounce time.Duration) quotaCacheStatus {
203		now := time.Now()
204		switch harnessName {
205		case "claude":
206			cachePath, err := claudeharness.ClaudeQuotaCachePath()
207			if err != nil {
208				return quotaCacheStatus{}
209			}
210			snap, _ := claudeharness.ReadClaudeQuotaFrom(cachePath)
211			if snap == nil {
212				return quotaCacheStatus{needsRefresh: true}
213			}
214			decision := claudeharness.DecideClaudeQuotaRouting(snap, now, debounce)
215			return quotaCacheStatus{
216				needsRefresh: !decision.Fresh,
217				usable:       decision.Fresh,
218			}
219		case "codex":
220			cachePath, err := codexharness.CodexQuotaCachePath()
221			if err != nil {
222				return quotaCacheStatus{}
223			}
224			snap, _ := codexharness.ReadCodexQuotaFrom(cachePath)
225			if snap == nil {
226				return quotaCacheStatus{needsRefresh: true}
227			}
228			decision := codexharness.DecideCodexQuotaRouting(snap, now, debounce)
229			return quotaCacheStatus{
230				needsRefresh: !decision.Fresh || !codexQuotaCacheComplete(snap),
231				usable:       decision.Fresh && decision.PreferCodex,
232			}
233		default:
234			return quotaCacheStatus{}
235		}
236	}
237	
238	func codexQuotaCacheComplete(snap *codexharness.CodexQuotaSnapshot) bool {
239		return snap != nil &&
240			!snap.CapturedAt.IsZero() &&
241			strings.TrimSpace(snap.Source) != "" &&
242			len(snap.Windows) > 0 &&
243			snap.Account != nil &&
244			strings.TrimSpace(snap.Account.PlanType) != ""
245	}
