247	// ListProviders returns providers known to the native-agent harness with live
248	// status, configured-default markers, and cooldown state.
249	func (s *service) ListProviders(ctx context.Context) ([]ProviderInfo, error) {
250		sc := s.opts.ServiceConfig
251		if sc == nil {
252			return nil, fmt.Errorf("service: no ServiceConfig provided; pass ServiceOptions.ServiceConfig")
253		}
254	
255		names := sc.ProviderNames()
256		defaultName := sc.DefaultProviderName()
257		cooldown := sc.HealthCooldown()
258		if cooldown <= 0 {
259			cooldown = 30 * time.Second
260		}
261	
262		type indexedInfo struct {
263			idx  int
264			info ProviderInfo
265		}
266		results := make([]indexedInfo, len(names))
267		var wg sync.WaitGroup
268	
269		for i, name := range names {
270			wg.Add(1)
271			go func(idx int, name string) {
272				defer wg.Done()
273	
274				entry, ok := sc.Provider(name)
275				if !ok {
276					results[idx] = indexedInfo{idx: idx, info: ProviderInfo{
277						Name:   name,
278						Status: "error: provider not found in config",
279					}}
280					return
281				}
282	
283				info := ProviderInfo{
284					Name:         name,
285					Type:         normalizeServiceProviderType(entry.Type),
286					BaseURL:      entry.BaseURL,
287					Endpoints:    append([]ServiceProviderEndpoint(nil), entry.Endpoints...),
288					IsDefault:    name == defaultName,
289					DefaultModel: entry.Model,
290				}
291	
292				probeCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
293				defer cancel()
294				capturedAt := time.Now().UTC()
295				probe := probeProviderStatus(probeCtx, entry, capturedAt)
296				info.Status = probe.status
297				info.ModelCount = probe.modelCount
298				info.Capabilities = probe.caps
299				info.CooldownState = serviceProviderCooldown(sc, name, cooldown)
300				info.Auth = providerAuthStatus(entry, info.Status, capturedAt)
301				info.EndpointStatus = probe.endpointStatuses
302				info.Quota = providerQuotaState(entry, capturedAt)
303				lastErrorSource := "service provider config"
304				if len(info.EndpointStatus) > 0 {
305					lastErrorSource = info.EndpointStatus[0].Source
306				}
307				info.LastError = statusErrorDetail(info.Status, probe.detail, lastErrorSource, capturedAt)
308	
309				results[idx] = indexedInfo{idx: idx, info: info}
310			}(i, name)
311		}
312		wg.Wait()
313	
314		out := make([]ProviderInfo, len(names))
315		for _, r := range results {
316			out[r.idx] = r.info
317		}
318		return out, nil
319	}
