321	// HealthCheck triggers a fresh probe for the named target and updates internal state.
322	// target.Type is "harness" or "provider".
323	func (s *service) HealthCheck(ctx context.Context, target HealthTarget) error {
324		switch target.Type {
325		case "provider":
326			sc := s.opts.ServiceConfig
327			if sc == nil {
328				return fmt.Errorf("service: no ServiceConfig provided; pass ServiceOptions.ServiceConfig")
329			}
330			entry, ok := sc.Provider(target.Name)
331			if !ok {
332				return fmt.Errorf("service: provider %q not found", target.Name)
333			}
334			probeCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
335			defer cancel()
336			probe := probeProviderStatus(probeCtx, entry, time.Now().UTC())
337			if probe.status == "connected" {
338				return nil
339			}
340			msg := probe.status
341			if probe.detail != "" {
342				msg = probe.detail
343			}
344			return fmt.Errorf("service: provider %q: %s", target.Name, msg)
345	
346		case "harness":
347			statuses := s.registry.Discover()
348			for _, st := range statuses {
349				if st.Name != target.Name {
350					continue
351				}
352				if !st.Available {
353					return fmt.Errorf("service: harness %q unavailable: %s", target.Name, st.Error)
354				}
355				// For subscription harnesses, refresh the quota cache when stale.
356				if target.Name == "claude" {
357					healthCheckRefreshClaudeQuota(ctx)
358				}
359				if target.Name == "codex" {
360					healthCheckRefreshCodexQuota(ctx)
361				}
362				return nil
363			}
364			return fmt.Errorf("service: harness %q not registered", target.Name)
365	
366		default:
367			return fmt.Errorf("service: unknown HealthTarget.Type %q (want \"harness\" or \"provider\")", target.Type)
368		}
369	}
