371	// probeServiceProvider pings a provider and returns (status, modelCount, capabilities).
372	func probeServiceProvider(ctx context.Context, entry ServiceProviderEntry) (status string, modelCount int, caps []string) {
373		probe := probeServiceProviderDetailed(ctx, entry)
374		return probe.status, probe.modelCount, probe.caps
375	}
376	
377	func probeServiceProviderDetailed(ctx context.Context, entry ServiceProviderEntry) providerProbeResult {
378		switch entry.Type {
379		case "anthropic":
380			if entry.APIKey == "" {
381				return providerProbeResult{status: "error: api_key not configured", detail: "api_key not configured"}
382			}
383			// Anthropic does not expose an unauthenticated /v1/models list endpoint.
384			// Treat key presence as the connectivity signal.
385			return providerProbeResult{status: "connected", caps: providerCapabilities(entry)}
386	
387		case "openai", "openrouter", "lmstudio", "omlx", "ollama", "minimax", "qwen", "zai", "":
388			if entry.BaseURL == "" {
389				return providerProbeResult{status: "error: base_url not configured", detail: "base_url not configured"}
390			}
391			n, err := discoverOpenAIModels(ctx, entry.BaseURL, entry.APIKey)
392			if err != nil {
393				msg := err.Error()
394				if serviceIsUnreachable(msg) {
395					return providerProbeResult{status: "unreachable", detail: serviceTrimError(msg)}
396				}
397				detail := serviceTrimError(msg)
398				return providerProbeResult{status: "error: " + detail, detail: detail}
399			}
400			return providerProbeResult{status: "connected", modelCount: n, caps: providerCapabilities(entry)}
401	
402		default:
403			detail := "unknown provider type " + entry.Type
404			return providerProbeResult{status: "error: " + detail, detail: detail}
405		}
406	}
407	
408	func probeProviderStatus(ctx context.Context, entry ServiceProviderEntry, capturedAt time.Time) providerProbeResult {
409		endpoints := modelDiscoveryEndpoints(entry)
410		if len(endpoints) == 0 {
411			probe := probeServiceProviderDetailed(ctx, entry)
412			probe.endpointStatuses = providerEndpointStatusesFromProbe(entry, probe, capturedAt)
413			return probe
414		}
415	
416		statuses := make([]EndpointStatus, 0, len(endpoints))
417		var aggregate providerProbeResult
418		aggregate.status = "error: endpoint probe did not run"
419		for _, endpoint := range endpoints {
420			endpointEntry := entry
421			endpointEntry.BaseURL = endpoint.BaseURL
422			endpointProbe := probeServiceProviderDetailed(ctx, endpointEntry)
423			endpointProbe.endpointName = endpoint.Name
424			endpointProbe.baseURL = endpoint.BaseURL
425			statuses = append(statuses, endpointStatusFromProbe(endpoint.Name, endpoint.BaseURL, endpointProbe, capturedAt))
426			if endpointProbe.status == "connected" {
427				if aggregate.status != "connected" {
428					aggregate.status = "connected"
429					aggregate.caps = append([]string(nil), endpointProbe.caps...)
430					aggregate.detail = ""
431				}
432				aggregate.modelCount += endpointProbe.modelCount
433				continue
434			}
435			if aggregate.status == "connected" {
436				continue
437			}
438			if shouldPreferProviderProbe(endpointProbe, aggregate) {
439				aggregate.status = endpointProbe.status
440				aggregate.detail = endpointProbe.detail
441				aggregate.caps = append([]string(nil), endpointProbe.caps...)
442				aggregate.baseURL = endpointProbe.baseURL
443				aggregate.endpointName = endpointProbe.endpointName
444			}
445		}
446		aggregate.endpointStatuses = statuses
447		return aggregate
448	}
