468	// This is a minimal inline version of provider/openai.DiscoverModels that avoids
469	// the import cycle (provider/openai imports the root agent package).
470	func discoverOpenAIModels(ctx context.Context, baseURL, apiKey string) (int, error) {
471		base := strings.TrimRight(baseURL, "/")
472		endpoint := base + "/models"
473	
474		req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
475		if err != nil {
476			return 0, fmt.Errorf("discovery: build request: %w", err)
477		}
478		req.Header.Set("Accept", "application/json")
479		if apiKey != "" {
480			req.Header.Set("Authorization", "Bearer "+apiKey)
481		}
482	
483		resp, err := http.DefaultClient.Do(req)
484		if err != nil {
485			return 0, err
486		}
487		defer resp.Body.Close()
488	
489		if resp.StatusCode != http.StatusOK {
490			body, _ := io.ReadAll(io.LimitReader(resp.Body, 512))
491			return 0, fmt.Errorf("discovery: %s returned HTTP %d: %s", endpoint, resp.StatusCode, strings.TrimSpace(string(body)))
492		}
493	
494		var mr struct {
495			Data []struct {
496				ID string `json:"id"`
497			} `json:"data"`
498		}
499		if err := json.NewDecoder(resp.Body).Decode(&mr); err != nil {
500			return 0, fmt.Errorf("discovery: decode response from %s: %w", endpoint, err)
501		}
502		return len(mr.Data), nil
503	}
