505	// serviceProviderCooldown scans all model routes for any candidate matching
506	// providerName and returns the first active CooldownState, or nil.
507	func serviceProviderCooldown(sc ServiceConfig, providerName string, cooldown time.Duration) *CooldownState {
508		if sc == nil {
509			return nil
510		}
511		now := time.Now().UTC()
512		for _, routeName := range sc.ModelRouteNames() {
513			for _, candidate := range sc.ModelRouteCandidates(routeName) {
514				if candidate != providerName {
515					continue
516				}
517				failures := serviceLoadRouteFailures(sc, routeName)
518				failedAt, hasFail := failures[providerName]
519				if !hasFail {
520					continue
521				}
522				until := failedAt.Add(cooldown)
523				if until.Before(now) {
524					continue
525				}
526				return &CooldownState{
527					Reason:    "consecutive_failures",
528					Until:     until,
529					FailCount: 1,
530				}
531			}
532		}
533		return nil
534	}
