621	// healthCheckRefreshClaudeQuota refreshes the Claude direct PTY quota cache when
622	// the cached snapshot is older than the default refresh debounce. It is a
623	// best-effort operation: errors are silently discarded so that a claude absence
624	// does not fail HealthCheck.
625	func healthCheckRefreshClaudeQuota(ctx context.Context) {
626		refreshClaudeQuotaCache(ctx, defaultQuotaRefreshDebounce, defaultQuotaRefreshProbeTimeout)
627	}
628	
629	func refreshClaudeQuotaCache(_ context.Context, debounce, timeout time.Duration) {
630		cachePath, err := claudeharness.ClaudeQuotaCachePath()
631		if err != nil {
632			return
633		}
634	
635		snap, _ := claudeharness.ReadClaudeQuotaFrom(cachePath)
636		if snap != nil && claudeharness.DecideClaudeQuotaRouting(snap, time.Now(), debounce).Fresh {
637			// Cache is fresh enough; skip the expensive PTY probe.
638			return
639		}
640	
641		// Cache is absent or stale - run a direct PTY probe with a bounded timeout.
642		windows, acct, probeErr := callHealthCheckClaudeQuotaRefresher(timeout)
643		if probeErr != nil || len(windows) == 0 {
644			return
645		}
646	
647		// Convert QuotaWindow slice to ClaudeQuotaSnapshot. The PTY path returns
648		// percent-based windows; synthesise remaining counts from UsedPercent.
649		newSnap := claudeharness.ClaudeQuotaSnapshot{
650			CapturedAt: time.Now().UTC(),
651			Source:     "pty",
652			Account:    acct,
653		}
654		for _, w := range windows {
655			switch w.LimitID {
656			case "session":
657				// 5-hour window; use a nominal limit of 100 so Remaining = 100-Used.
658				used := int(w.UsedPercent)
659				newSnap.FiveHourLimit = 100
660				newSnap.FiveHourRemaining = 100 - used
661			case "weekly-all", "weekly-sonnet":
662				used := int(w.UsedPercent)
663				newSnap.WeeklyLimit = 100
664				newSnap.WeeklyRemaining = 100 - used
665			}
666		}
667	
668		_ = claudeharness.WriteClaudeQuota(cachePath, newSnap)
669	}
