337	// buildRoutingInputs assembles routing.Inputs from the service's registry
338	// and ServiceConfig. When the service has a catalog cache attached (v0.9.2+),
339	// each configured provider's ProviderEntry is populated with DiscoveredIDs
340	// from the cache's live /v1/models probe, so routing.FuzzyMatch matches the
341	// request against IDs the server actually serves rather than the configured
342	// default-model string.
343	//
344	// ctx is used for cache probes with a short deadline; the cache's
345	// stale-while-revalidate flow makes most calls non-blocking.
346	func (s *service) buildRoutingInputs(ctx context.Context) routing.Inputs {
347		return s.buildRoutingInputsWithCatalog(ctx, serviceRoutingCatalog())
348	}
349	
350	func (s *service) buildRoutingInputsWithCatalog(ctx context.Context, cat *modelcatalog.Catalog) routing.Inputs {
351		statuses := s.registry.Discover()
352		statusByName := make(map[string]harnesses.HarnessStatus, len(statuses))
353		for _, st := range statuses {
354			statusByName[st.Name] = st
355		}
356	
357		var entries []routing.HarnessEntry
358		for _, name := range s.registry.Names() {
359			cfg, ok := s.registry.Get(name)
360			if !ok {
361				continue
362			}
363			st := statusByName[name]
364			entry := routing.HarnessEntry{
365				Name:                name,
366				Surface:             cfg.Surface,
367				CostClass:           cfg.CostClass,
368				IsLocal:             cfg.IsLocal,
369				IsSubscription:      cfg.IsSubscription,
370				IsHTTPProvider:      cfg.IsHTTPProvider,
371				AutoRoutingEligible: cfg.AutoRoutingEligible,
372				TestOnly:            cfg.TestOnly,
373				ExactPinSupport:     cfg.ExactPinSupport,
374				DefaultModel:        cfg.DefaultModel,
375				SupportedModels:     subprocessHarnessModelIDs(name, cfg),
376				SupportedReasoning:  supportedReasoning(cfg),
377				MaxReasoningTokens:  cfg.MaxReasoningTokens,
378				SupportedPerms:      supportedPermissions(cfg),
379				SupportsTools:       true, // all builtin harnesses support tools today
380				Available:           st.Available,
381				QuotaOK:             true,
382				QuotaTrend:          routing.QuotaTrendUnknown,
383				// SubscriptionOK defaults to true and is refined by subscription
384				// harness quota caches below.
385				SubscriptionOK: true,
386			}
387			if name == "agent" && s.opts.ServiceConfig == nil {
388				entry.AutoRoutingEligible = false
389			}
390	
391			if name == "claude" {
392				dec := claudeharness.ReadClaudeQuotaRoutingDecision(time.Now(), 0)
393				entry.QuotaOK = dec.PreferClaude
394				entry.QuotaStale = !dec.Fresh && dec.SnapshotPresent
395				entry.SubscriptionOK = dec.PreferClaude
396				if dec.Snapshot != nil {
397					maxUsed := 0.0
398					if dec.Snapshot.FiveHourLimit > 0 {
399						maxUsed = float64(dec.Snapshot.FiveHourLimit-dec.Snapshot.FiveHourRemaining) / float64(dec.Snapshot.FiveHourLimit) * 100

400					}
401					if dec.Snapshot.WeeklyLimit > 0 {
402						weeklyUsed := float64(dec.Snapshot.WeeklyLimit-dec.Snapshot.WeeklyRemaining) / float64(dec.Snapshot.WeeklyLimit) * 100
403						if weeklyUsed > maxUsed {
404							maxUsed = weeklyUsed
405						}
406					}
407					entry.QuotaPercentUsed = int(maxUsed)
408					if maxUsed >= 90 {
409						entry.QuotaTrend = routing.QuotaTrendExhausting
410					} else if maxUsed >= 70 {
411						entry.QuotaTrend = routing.QuotaTrendBurning
412					} else if dec.Fresh {
413						entry.QuotaTrend = routing.QuotaTrendHealthy
414					}
415				}
416			}
417	
418			if name == "codex" {
419				dec := codexharness.ReadCodexQuotaRoutingDecision(time.Now(), 0)
420				entry.QuotaOK = dec.PreferCodex
421				entry.QuotaStale = !dec.Fresh && dec.SnapshotPresent
422				entry.SubscriptionOK = dec.PreferCodex
423				if dec.Snapshot != nil {
424					maxUsed := 0.0
425					for _, window := range dec.Snapshot.Windows {
426						if window.UsedPercent > maxUsed {
427							maxUsed = window.UsedPercent
428						}
429					}
430					entry.QuotaPercentUsed = int(maxUsed)
431					if maxUsed >= 90 {
432						entry.QuotaTrend = routing.QuotaTrendExhausting
433					} else if maxUsed >= 70 {
434						entry.QuotaTrend = routing.QuotaTrendBurning
435					} else if dec.Fresh {
436						entry.QuotaTrend = routing.QuotaTrendHealthy
437					}
438				}
439			}
440	
441			if name == "gemini" {
442				// Auth freshness is NOT quota. Only parsed quota evidence
443				// (from PTY /model manage capture) may mark Gemini as
444				// quota-OK for routing. Missing or stale quota evidence
445				// keeps Gemini out of automatic routing regardless of
446				// authentication state.
447				dec := geminiharness.ReadGeminiQuotaRoutingDecision(time.Now(), 0)
448				entry.QuotaOK = dec.PreferGemini
449				entry.QuotaStale = !dec.Fresh && dec.SnapshotPresent
450				entry.SubscriptionOK = dec.PreferGemini
451				if dec.Snapshot != nil {
452					maxUsed := dec.Snapshot.MaxUsedPercent()
453					entry.QuotaPercentUsed = int(maxUsed)
454					if len(dec.ExhaustedTiers) > 0 && len(dec.AvailableTiers) == 0 {
455						entry.QuotaTrend = routing.QuotaTrendExhausting
456					} else if maxUsed >= 90 {
457						entry.QuotaTrend = routing.QuotaTrendExhausting
458					} else if maxUsed >= 70 {
459						entry.QuotaTrend = routing.QuotaTrendBurning
460					} else if dec.Fresh {
461						entry.QuotaTrend = routing.QuotaTrendHealthy
462					}
463				}
464			}
465	
466			// Native "agent" harness: enumerate live configured provider endpoints.
467			if name == "agent" && s.opts.ServiceConfig != nil {
468				for _, pname := range s.opts.ServiceConfig.ProviderNames() {
469					pcfg, ok := s.opts.ServiceConfig.Provider(pname)
470					if !ok {
471						continue
472					}
473					entry.Providers = append(entry.Providers, s.liveProviderEntries(ctx, pname, pcfg, cat)...)
474				}
475				// Tool support for the agent harness is per-(provider, model);
476				// the harness-level baseline is whether ANY provider supports
477				// tools. Engine OR-combines harness and provider SupportsTools
478				// so this lets a per-model no_tools catalog flag actually fire
479				// the RequiresTools gate when every provider's resolved model
480				// is no-tools.
481				if len(entry.Providers) > 0 {
482					entry.SupportsTools = anyProviderSupportsTools(entry.Providers)
483				}
484			}
485			s.applySubscriptionRoutingCost(&entry, cat)
486			entries = append(entries, entry)
487		}
488		successRate, latencyMS := s.routeMetricSignals(time.Now(), s.routeAttemptTTL())
489		return routing.Inputs{
490			Harnesses:           entries,
491			ProviderSuccessRate: successRate,
492			ObservedLatencyMS:   latencyMS,
493			CatalogResolver:     serviceRoutingCatalogResolver(cat),
494			ModelEligibility:    serviceRoutingModelEligibility(cat),
495			ReasoningResolver:   serviceRoutingReasoningResolver(cat),
496		}
497	}
